insert into ejes (id,nombre,orden) values ('participacion_ciudadana','Participación ciudadana',3) on conflict (id) do update set nombre=excluded.nombre, orden=excluded.orden;
insert into ejes (id,nombre,orden) values ('lucha_contra_discriminacion','Lucha contra la discriminación',4) on conflict (id) do update set nombre=excluded.nombre, orden=excluded.orden;
