insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (1,'GOP + Jovem, Presupuesto Participativo Juvenil de Vila Nova de Gaia','GOP + Jovem en Vila Nova de Gaia','Portugal / Área Metropolitana de Oporto / Vila Nova de Gaia. Câmara Municipal de Vila Nova de Gaia, a través de su División Municipal de Juventud.','Portugal','Innovation in Politics Awards 2025, categoría Democracia. Organización: European Capital of Democracy (ECoD); premio creado por The Innovation in Politics Institute. Entrega: 17 de septiembre de 2025, Viena. También documentado por la OCDE.','participacion_juvenil',array['participacion_juvenil','fortalecimiento_democratico']::text[],'Inicio: 2019, según la OCDE. Periodo documentado: desde su creación hasta la edición municipal de 2025. No se acredita una convocatoria en 2026.','Ampliar la intervención de las juventudes en las decisiones públicas y su conocimiento del presupuesto y de las competencias municipales.','La municipalidad convoca propuestas juveniles, organiza su selección mediante votación y financia proyectos ganadores con un presupuesto definido. Edición 2025: 240.000 euros, con un máximo de 40.000 por proyecto (asignación de esa edición, no un costo de réplica en Perú). Temas 2025: artes y creatividad; bienestar y ambiente; capacitación y participación juvenil.','Jóvenes de 13 a 30 años de Gaia. Proyectos como Serzedo benefician también a otras edades.','El Parque Multigeneracional de Serzedo, ganador de la edición 2020, fue inaugurado el 19 de febrero de 2025. Incluye espacios para infancia, personas adultas y mayores. La nota municipal acredita una obra terminada; no constituye una evaluación del impacto de todo el programa.','Una partida identificable y reglas públicas permiten explicar qué puede decidir la juventud. La entrega de proyectos ofrece un resultado visible del proceso participativo.','El caso de Serzedo muestra una distancia entre la selección de 2020 y la inauguración de 2025; la fuente no explica sus causas.','Publicar hitos de ejecución y comunicar las demoras.','Para Lima: pilotear una convocatoria metropolitana articulada con distritos y organizaciones juveniles afroperuanas y andinas. Para Huamanga: combinar convocatoria urbana y comunitaria, facilitación en quechua cuando corresponda y presentación presencial de ideas.','Identificar el mecanismo participativo existente, la competencia municipal y una partida viable; acordar edades y reglas; ofrecer apoyo para formular propuestas y evitar que el acceso digital determine quién participa. La pertinencia étnica debe diseñarse con las propias juventudes.','Reunir al área de juventud, presupuesto y organizaciones juveniles para acordar el alcance de un piloto y elaborar una ficha sencilla de propuesta, con problema, solución, costo estimado y población beneficiaria.','Presupuesto participativo juvenil, reglamento y normas de participación; plataforma municipal de propuestas y votación. Referencia: reglamento y normas de participación del portal GOP + Jovem [4]; recuadro 3.5 de la publicación de la OCDE [1]; noticia municipal de ejecución de Serzedo [3].',array['[1] OCDE (2022). Youth at the Centre of Government Action, capítulo 3, recuadro 3.5.','[2] Municipalidad de Gaia. GOP + Jovem 2025, condiciones y documentación.','[3] Municipalidad de Gaia (19/02/2025). Parque Multigeracional de Serzedo.','[4] Municipalidad de Gaia. Reglamentos y normas de participación.','[5] The Innovation in Politics Institute (18/09/2025). Ganadores de los Innovation in Politics Awards 2025; ceremonia del 17/09/2025.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (2,'GANA Municipales, Presupuesto participativo de la Gobernación de Nariño','GANA Municipales en Nariño','Colombia / Departamento de Nariño / municipios del departamento. Gobernación de Nariño, con despliegue en municipios (iniciativa departamental con aplicación municipal).','Colombia','Ganadora de la 13.ª Distinción Buena Práctica en Participación Ciudadana, edición 2019. Entidad otorgante: Observatorio Internacional de la Democracia Participativa (OIDP). La comunicación del premio la vincula al ejercicio Nuevo Gobierno.','fortalecimiento_democratico',array['fortalecimiento_democratico','participacion_ciudadana']::text[],'Documentada en la candidatura de 2019 y vinculada al Plan Participativo de Desarrollo Nariño 2016–2019. Las fuentes no acreditan su continuidad posterior.','Incorporar las prioridades de comunidades mayoritariamente rurales a las decisiones de inversión pública, en un territorio afectado por el conflicto y con dificultades de conectividad.','La Gobernación desplaza su equipo al territorio y somete los proyectos a votación ciudadana. Una plataforma que funciona en red local permite votar sin conexión a internet. Priorización de inversión mediante voto; asignación territorial según población y necesidades básicas insatisfechas; información y rendición de cuentas valoradas por el jurado. Financiamiento departamental asociado a regalías.','Ciudadanía mayor de 18 años de los municipios participantes; comunidades rurales y urbanas.','La candidatura de 2019 reporta casi 100.000 participantes y describe el despliegue en los 64 municipios. Son cifras declaradas por la entidad postulante. El OIDP confirma el premio y destaca la combinación de participación presencial, tecnología y rendición de cuentas; no acredita por sí solo el impacto de cada inversión.','Acercar al equipo técnico al territorio y permitir participación sin internet reduce barreras operativas. La información previa sobre proyectos ayuda a que la elección ciudadana tenga un objeto definido.','La candidatura identifica la falta de internet en zonas apartadas y describe una solución con red local.','Debe evitarse que la ciudadanía solo pueda escoger opciones definidas sin recoger antes sus necesidades.','Para Lima: presentar proyectos municipales viables en lenguaje sencillo y recoger prioridades con organizaciones afroperuanas y andinas, coordinando con distritos. Para Huamanga: realizar jornadas descentralizadas y devolver a comunidades y barrios el estado de los proyectos priorizados.','Delimitar los recursos sobre los que puede decidir el municipio peruano, revisar el proceso participativo vigente y fijar criterios públicos de viabilidad. La fuente de regalías colombiana no constituye un mecanismo de financiamiento trasladable automáticamente.','Seleccionar con organizaciones locales un problema concreto y elaborar dos o tres alternativas viables, con costos orientativos y competencia municipal, para una primera sesión pública de priorización.','Plan departamental de desarrollo, proyectos tipo, jornadas de votación y plataforma de decisión. Referencia: candidatura GANA Municipales [1], que describe la metodología y la plataforma; decisión del jurado OIDP [2]. El número de proyectos tipo varía entre ambas fuentes, por lo que no se usa como resultado consolidado.',array['[1] Gobernación de Nariño (2019). Candidatura GANA Municipales ante el OIDP.','[2] OIDP (2019). Nariño gana la 13.ª Distinción a la Buena Práctica en Participación Ciudadana.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (3,'Construcción participativa de las escuelas para el buen vivir. Recuperando saberes locales','Escuelas para el Buen Vivir en Ccarhuayo','Perú / Cusco / provincia de Quispicanchi / distrito de Ccarhuayo. Municipalidad Distrital de Ccarhuayo, en convenio con la Unidad de Gestión Educativa Local (UGEL) de Quispicanchi.','Perú','Ganadora del concurso Buenas Prácticas Interculturales en Gestión Pública 2014, categoría Gobierno Local. Entidad otorgante: Ministerio de Cultura del Perú. Premiación comunicada el 11 de diciembre de 2014.','interculturalidad',array['interculturalidad','participacion_ciudadana']::text[],'Inicio: 2013. Experiencia premiada en 2014 y sistematizada por el Ministerio de Cultura en 2016. No se acredita su funcionamiento actual.','Adecuar la educación rural a las necesidades culturales de la niñez y mejorar sus aprendizajes.','El municipio y la UGEL promovieron un modelo escolar construido con la comunidad, incorporando lengua quechua, saberes locales y participación familiar en las decisiones educativas. Transmisión intergeneracional, juegos tradicionales, uso de quechua y castellano, y adecuación de espacios escolares. La ficha publicada no consigna presupuesto desagregado.','Público objetivo registrado: 350 niñas y niños de escuelas rurales (población prevista en la ficha, no una medición independiente de cobertura final). Actores: municipalidad, UGEL, docentes, niñas y niños, familias y personas sabias de las comunidades.','El Ministerio reporta mejoras de aprendizaje en comunicación y matemática de segundo grado, sin porcentajes comparables en esa ficha. Documenta cuadernos de sabiduría y mayor intervención de las familias. La evidencia es una sistematización institucional, sin estimación causal independiente.','El acuerdo entre municipio, comunidad y entidad educativa permite distribuir responsabilidades. Reconocer a las familias como productoras de conocimiento da contenido a su participación.','La ficha no detalla dificultades específicas del caso.','Prever tiempos de concertación y acuerdos sobre el uso de los saberes; una actividad cultural aislada no sustituye la participación en el diseño del servicio.','Para Huamanga: codiseñar un espacio cultural o educativo municipal con hablantes de quechua, familias y jóvenes. Para Lima: incorporar memorias, conocimientos y expresiones afroperuanas y andinas a bibliotecas y programas culturales, con participación de sus organizaciones. La adaptación a juventudes es una propuesta distinta del público infantil original.','Escoger un servicio bajo competencia municipal; coordinar con la UGEL si involucra escuelas; acordar participación y reconocimiento de las personas portadoras de saberes. Consultar necesidades concretas y evitar reducir la identidad a vestimenta o espectáculos.','Organizar una sesión de diseño entre el responsable de una biblioteca o espacio cultural municipal y organizaciones afroperuanas y andinas para acordar un taller intergeneracional y cómo evaluarán su pertinencia.','Convenio municipal con la UGEL; enfoque de educación intercultural bilingüe; cuadernos de sabiduría elaborados con las familias. Referencia: Ministerio de Cultura, Buenas Prácticas Interculturales en la Gestión Pública, pp. 85–88 impresas [1]; nota oficial de premiación, categoría Gobierno Local [2].',array['[1] Ministerio de Cultura (2016). Buenas Prácticas Interculturales en la Gestión Pública, experiencias 2014–2015, pp. 85–88.','[2] Ministerio de Cultura (11/12/2014). Entrega de premios de Buenas Prácticas Interculturales en Gestión Pública.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (4,'La gestión pública en el fortalecimiento productivo y social: una experiencia participativa en asociación con las comunidades campesinas de Huachis','Gestión productiva y social en Huachis','Perú / Áncash / provincia de Huari / distrito de Huachis. Municipalidad Distrital de Huachis.','Perú','Mención especial de la 8.ª Distinción Buena Práctica en Participación Ciudadana, edición 2014. Entidad otorgante: Observatorio Internacional de la Democracia Participativa (OIDP).','participacion_ciudadana',array['participacion_ciudadana']::text[],'Del 2 de enero de 2011 al 31 de diciembre de 2014, según la candidatura. Se presenta como experiencia histórica.','Mejorar ingresos y condiciones de vida rurales mediante inversión productiva, riego y organización de productores.','El municipio articuló presupuesto participativo y planificación concertada en ejes social, productivo y de infraestructura; formuló proyectos y planes de negocio con comunidades. Organización asociativa, selección de actividades según condiciones territoriales, capacitación y articulación comercial. Convenios con SENASA, AGRORURAL, AGROIDEAS, Sierra Exportadora y Antamina. La documentación no desagrega el presupuesto total.','Comuneros y productores agropecuarios. La candidatura reporta al menos 50 % de mujeres en las asociaciones participantes.','El registro OIDP documenta biohuertos en 18 instituciones educativas, laboratorios en dos, 20 juntas vecinales y capacitación de 20 maestros de obra. La candidatura refiere mejoras de producción e ingresos, pero no aporta una serie monetaria que permita cuantificar el cambio.','Relacionar prioridades comunitarias, condiciones productivas y mercado evita formular proyectos sin salida comercial. Las alianzas pueden complementar capacidades del municipio.','La candidatura señala desconfianza inicial ante las propuestas tecnológicas y uso de visitas de campo y capacitación para ampliar la participación.','Acordar cambios con los productores y demostrar su utilidad respetando sus conocimientos.','Para Huamanga: fortalecer la participación de organizaciones de productores, mujeres y jóvenes en iniciativas económicas existentes. Para Lima: adaptar el diagnóstico y la asistencia técnica a emprendimientos urbanos afroperuanos y andinos. Las actividades agropecuarias originales no se trasladan íntegramente al contexto metropolitano.','Revisar instrumentos de desarrollo económico ya disponibles y sus requisitos de financiamiento; identificar demanda real y costos de mantenimiento; asegurar que mujeres y jóvenes intervengan en las decisiones de las asociaciones. No confundir entrega de insumos con incremento sostenido de ingresos.','Convocar una reunión con asociaciones de un territorio para identificar una barrera productiva común y acordar qué diagnóstico técnico o comercial debe realizar el municipio antes de financiar una intervención.','Plan de Desarrollo Concertado, presupuesto participativo, convenios, planes de negocio y estudios productivos y de mercado. Referencia: publicación de la VIII Distinción OIDP 2014, ficha de Huachis, páginas 44–46 del PDF [1]; registro institucional de la experiencia [2].',array['[1] OIDP (2014). VIII Distinción Buena Práctica en Participación Ciudadana, ficha de Huachis, páginas 44–46 del PDF.','[2] OIDP. La gestión pública en el fortalecimiento productivo y social, registro de Huachis.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (5,'Procesos y mecanismos de inclusión de las mujeres indígenas en la gestión local, Presupuesto Participativo de Cotacachi','Participación de mujeres indígenas en Cotacachi','Ecuador / provincia de Imbabura / cantón Cotacachi. Municipio de Cotacachi, articulado con la Asamblea de Unidad Cantonal.','Ecuador','Ganadora de la 1.ª Distinción Buena Práctica en Participación Ciudadana, edición 2006. Entidad otorgante: Observatorio Internacional de la Democracia Participativa (OIDP).','participacion_ciudadana',array['participacion_ciudadana','interculturalidad','lucha_contra_discriminacion','enfoque_genero']::text[],'Antecedentes: gestión participativa desde 1996 y elaboración participativa del presupuesto desde 2000. Metodología específica de inclusión de mujeres desde 2003; sistematización premiada en 2006. Se analiza ese periodo histórico.','Superar barreras de género, lengua y alfabetización que limitaban la voz de mujeres indígenas en decisiones locales.','El municipio facilitó espacios propios de mujeres, priorización de propuestas y participación en el seguimiento del presupuesto. Lengua originaria, materiales visuales y cotidianos, reuniones autónomas de mujeres y devolución de prioridades al proceso cantonal. La fuente no ofrece un costo integral de operación.','Mujeres indígenas, especialmente rurales; el proceso cantonal también comprende mujeres de otras zonas y grupos.','La publicación documenta la participación femenina en el seguimiento presupuestario y una oficina de atención a la mujer operativa desde 2005. El reporte de 2006 no demuestra continuidad actual ni impactos causales.','Preparar la participación antes de la reunión general puede mejorar las condiciones para que las mujeres formulen propuestas propias. Vincular esas propuestas con recursos y seguimiento da continuidad a su intervención.','La sistematización describe restricciones sociales para tomar la palabra.','Acordar con las participantes condiciones de horario, cuidado, desplazamiento y uso de lengua. La convocatoria por sí sola no demuestra incidencia.','Para Huamanga: preparar propuestas con organizaciones de mujeres quechuas y acompañar su incorporación al presupuesto participativo. Para Lima: trabajar con organizaciones de mujeres afroperuanas y andinas, registrando las propuestas aceptadas, pendientes o rechazadas y sus razones. Incluir a jóvenes sin desplazar a las organizaciones existentes.','Partir del proceso municipal vigente; identificar barreras con las propias participantes; asignar personal que dé respuesta a sus propuestas. Los espacios autónomos deben acordarse con ellas y conectarse con decisiones municipales efectivas.','Realizar una reunión preparatoria con organizaciones de mujeres y abrir una matriz sencilla de propuestas, respuesta municipal y seguimiento, que acompañe la siguiente instancia participativa.','Presupuesto participativo, talleres y comités de seguimiento. Referencia: publicación OIDP sobre Cotacachi, especialmente las secciones de actores, metodología, resultados y conclusiones [1].',array['[1] Municipio de Cotacachi y OIDP (2006). Procesos y mecanismos de inclusión de las mujeres indígenas en la gestión local, páginas 1–9 del PDF.','[2] Municipios Abiertos Ecuador (s. f.). Procesos y mecanismos de inclusión de las mujeres indígenas en la gestión local.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (6,'Escuela de Liderazgo de Mujeres para Ciudades Seguras','Liderazgo de mujeres para ciudades seguras','Guatemala / departamento de Izabal (la documentación también registra participantes de otras localidades). Iniciativa de Fundación Guatemala en cinco municipios de Izabal; el premio corresponde a la fundación. El programa marco incluyó colaboración municipal; no se presenta la Escuela como creación de una alcaldía.','Guatemala','Tercer Premio a las Buenas Prácticas Locales con Enfoque de Género, II edición, 2013. Entidad otorgante: Unión Iberoamericana de Municipalistas (UIM). Fallo: 30 de agosto; publicación: 2 de septiembre de 2013.','participacion_ciudadana',array['participacion_ciudadana','interculturalidad','fortalecimiento_democratico','enfoque_genero']::text[],'Escuela documentada y premiada en 2013, dentro del programa Ciudades Seguras desarrollado en Guatemala en 2008–2013. No se acredita el año exacto de inicio de la Escuela ni su continuidad hasta 2026.','Fortalecer la capacidad de las lideresas para organizarse e incidir frente a la violencia en ámbitos públicos y privados, en un territorio con población indígena y garífuna.','Fundación Guatemala desarrolló formación en derechos de las mujeres, ciudades seguras y estrategias de incidencia. El jurado valoró la mejora de capacidades organizativas y de argumentación política. Es formación para la participación; no asignación de escaños étnicos. Las fuentes no precisan el costo total de la Escuela; para un piloto peruano se propone prever facilitación, local, materiales, movilidad, apoyos de cuidado y accesibilidad lingüística.','Mujeres lideresas de comunidades y municipios; pertinencia indígena y garífuna en Izabal. Incluyó autoridades auxiliares y responsables de oficinas de la mujer. No se documenta una focalización exclusiva en jóvenes.','La evaluación externa de 2013 registra 130 mujeres comunitarias formadas y una cuarta Escuela en curso. Es alcance formativo, sin desglose étnico completo ni prueba de acceso a cargos públicos. No debe sumarse a las cifras parciales de fases anteriores.','Combinar formación con organización e interlocución local puede convertir necesidades en propuestas. Para la adaptación, el municipio debe acordar un canal de recepción y respuesta a las iniciativas de las participantes.','La evaluación del programa marco advierte ausencia de línea de base, lo que limita la medición del impacto.','Registrar capacidades iniciales, permanencia, propuestas presentadas y respuestas municipales; distinguir asistencia de incidencia efectiva.','Propuesta peruana: Escuela Municipal de Liderazgo e Incidencia de Mujeres Afroperuanas y Andinas. En Lima: convocatoria con organizaciones y distritos. En Huamanga: articulación con comunidades y barrios, con facilitación en quechua según necesidad. Priorizar lideresas jóvenes y cerrar la formación con propuestas de seguridad e inclusión presentadas al municipio.','Codiseñar el piloto con las organizaciones; revisar oferta existente, competencia municipal y presupuesto. Acordar selección transparente, horarios y apoyos de participación. Establecer interlocución con áreas responsables y seguimiento público. La participación en la Escuela no otorga representación electiva ni reemplaza la designación autónoma de representantes.','Reunir a organizaciones de mujeres afroperuanas y andinas y al equipo municipal para acordar un piloto: población, tres necesidades prioritarias, responsables de formación y mecanismo de respuesta a sus propuestas. En Huamanga, consultar la presencia y necesidades de ambos grupos sin asumir igual composición demográfica.','Escuela de liderazgo, formación en derechos y herramientas para ciudades seguras. Como referencia complementaria: guía de herramientas y evaluación externa del programa marco. Referencia: fallo del premio UIM [1]; descripción de la Escuela por Fundación Guatemala [2]; evaluación externa publicada por ONU Mujeres, pp. 16 y 40 [3]. El componente andino es una adaptación propuesta para Perú.',array['[1] UIM (02/09/2013). Fallo de la II edición de los premios a las buenas prácticas locales con enfoque de género.','[2] Fundación Guatemala (s. f.). Programa Ciudades Seguras y Escuela de Liderazgo de Mujeres.','[3] Suárez Trueba y Bolaños Vargas (2013). Evaluación final del Programa Ciudades Seguras de ONU Mujeres Guatemala.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (7,'Construyendo Ciudadanía','Construyendo Ciudadanía en San Luis Potosí','México / estado de San Luis Potosí / municipio de San Luis Potosí. Ayuntamiento de San Luis Potosí.','México','Ganadora de la 19.ª Distinción Buena Práctica en Participación Ciudadana. Entidad otorgante: Observatorio Internacional de la Democracia Participativa (OIDP). Entrega: 21 de mayo de 2025, Córdoba, Argentina.','fortalecimiento_democratico',array['fortalecimiento_democratico','participacion_ciudadana']::text[],'Diseño en 2021 e implementación desde enero de 2022. La candidatura de 2025 la registra en vigor, vinculada a los planes municipales 2021–2024 y 2024–2027.','Atender la desconexión entre ciudadanía y gobierno y las desigualdades de acceso a servicios.','El ayuntamiento organizó representación por demarcaciones, eligió juntas ciudadanas y las vinculó con diagnóstico, priorización y seguimiento de acciones municipales. Representación territorial, formación de integrantes, diálogo con el gobierno y combinación de actividades presenciales y canales digitales. La ficha registra $983.927,70 sin aclarar moneda ni periodo, por lo que no se usa como costo comparable.','Habitantes de barrios y comunidades rurales del municipio. El enfoque étnico específico para Perú es una propuesta de adaptación.','El OIDP confirmó la constitución de 284 juntas. La candidatura reporta más de 35.000 votantes en 2022 y 390 espacios públicos rehabilitados mediante Domingos de Pilas. Las cifras son reportes de la postulación; la cobertura territorial no equivale a que toda la población participe activamente.','Las juntas ofrecen interlocutores territoriales continuos y pueden vincular necesidades con servicios concretos. La devolución de respuestas evita que las reuniones se limiten a recoger solicitudes.','El diagnóstico reconoce apatía y desigualdad de servicios; no se publica en las fuentes seleccionadas una evaluación independiente de dificultades operativas.','Revisar participación efectiva, rotación de representantes y cumplimiento de acuerdos, además del número de juntas.','Para Lima: fortalecer la conexión entre organizaciones vecinales, distritos y áreas metropolitanas competentes. Para Huamanga: vincular barrios, centros poblados y comunidades a reuniones periódicas con respuesta municipal. Incorporar organizaciones afroperuanas y andinas y juventudes donde estén presentes.','Mapear juntas e instancias ya existentes; acordar funciones y mecanismos de representación; asegurar personal responsable de tramitar solicitudes. La creación de más espacios debe justificarse frente a la posibilidad de mejorar los actuales.','Elegir una junta o instancia territorial existente y acordar una reunión con el área municipal competente, dejando un registro público de solicitudes, responsables y fechas de respuesta.','Ley estatal de Juntas de Participación Ciudadana; planes municipales de desarrollo; juntas, consejo y matriz de indicadores. Referencia: ficha completa de candidatura, con método e indicadores [2]; comunicación del jurado OIDP [1]. La ficha enlaza anexos y el sitio municipal del programa.',array['[1] OIDP (2025). San Luis Potosí gana la 19.ª Distinción por Construyendo Ciudadanía.','[2] Ayuntamiento de San Luis Potosí (2025). Candidatura Construyendo Ciudadanía ante el OIDP.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
insert into fichas (numero,nombre_accion,nombre_corto,lugar,pais,reconocimiento,eje_principal,ejes,periodo,desafio_inicial,descripcion,poblacion,resultados_alcanzados,factores_exito,dificultades,aprendizajes,elementos_adaptables,condiciones_adaptacion,accion_sugerida,instrumentos,fuentes_verificacion) values (8,'Centro Especializado de Atendimento à Mulher (CEAM) Brasilete Ramos Caiado','Atención integral a mujeres en Goiás','Brasil / estado de Goiás / municipio de Goiás (no corresponde a la ciudad de Goiânia). Gobierno municipal de la ciudad de Goiás, a través del CEAM.','Brasil','Premio Construir Igualdad, edición 2020; categoría Áreas Urbanas de hasta un millón de habitantes. Entidad otorgante: Centro Internacional para la Promoción de los Derechos Humanos (CIPDH-UNESCO), con apoyo de UNESCO Montevideo. Entrega: 7 de enero de 2021, ceremonia virtual.','lucha_contra_discriminacion',array['lucha_contra_discriminacion','enfoque_genero']::text[],'Inicio: 2013. Reconocimiento: edición 2020 del premio, entregada el 7 de enero de 2021. Documentación institucional consultada: 2019–2021; no acredita continuidad operativa hasta 2026.','Responder a la violencia contra mujeres y niñas y sus consecuencias, promoviendo la igualdad de género.','El gobierno local ofrece un espacio de orientación, acogida y acompañamiento interdisciplinario a mujeres en situación de violencia, junto con acciones preventivas (charlas, cursos y talleres). Atención integral; apoyo a la autonomía emocional y económica; enfoque interseccional reconocido por el jurado. Las fuentes no desagregan presupuesto ni dotación de personal.','Mujeres en situación de violencia, especialmente doméstica. Las fuentes no acreditan un programa específico para comunidades quilombolas.','La CNM documenta la oferta de acogida, acompañamiento y prevención. UNESCO y CIPDH acreditan el reconocimiento externo. Estas fuentes no publican una cifra comparable de usuarias atendidas ni una reducción atribuible de la violencia; esos impactos no se afirman.','Acompañar varias necesidades de una misma usuaria puede facilitar la continuidad de la atención. La coordinación debe traducirse en derivaciones efectivas y trato respetuoso, aspectos que requieren seguimiento.','No se dispone en estas fuentes de una evaluación específica de obstáculos del centro.','Prevenir la revictimización y comprobar si las derivaciones se completan, considerando barreras de lengua, racismo, discapacidad y dependencia económica.','Para Lima y Huamanga: mejorar la articulación municipal con los servicios especializados existentes. Codiseñar con organizaciones de mujeres afroperuanas y andinas medidas de trato sin discriminación y acceso lingüístico. Este enfoque étnico concreto constituye una propuesta para Perú.','Mapear la oferta existente y las responsabilidades de cada entidad; coordinar con los servicios competentes del MIMP, salud y justicia; asegurar confidencialidad y consentimiento. El objetivo de la adaptación es cerrar barreras de acceso y continuidad, evitando duplicar servicios.','Reunir a responsables municipales, servicios especializados y organizaciones de mujeres para identificar una barrera de acceso y acordar una mejora concreta de orientación o derivación, con responsable de seguimiento.','Servicio municipal especializado y actividades de prevención mediante charlas, cursos y talleres. Referencia: ficha CNM Centro Especializado de Atendimento à Mulher, colección MuniCiência, 2021 [3]; descripción CIPDH del centro y del premio [2]; nota informativa de UNESCO de premiación [1].',array['[1] UNESCO (19/01/2021). Ciudad de México y Goiás, ganadoras del Premio Construir Igualdad 2020.','[2] CIPDH (s. f.). Premio Construir Igualdad 2020 y descripción del CEAM.','[3] Confederação Nacional de Municípios (2021). Centro Especializado de Atendimento à Mulher Brasilete Ramos Caiado, Goiás GO.','[4] Confederação Nacional de Municípios (2019). Visita al CEAM de Goiás; inicio en 2013 y acompañamiento interdisciplinario.']::text[]) on conflict (numero) do update set nombre_accion=excluded.nombre_accion, nombre_corto=excluded.nombre_corto, lugar=excluded.lugar, pais=excluded.pais, reconocimiento=excluded.reconocimiento, eje_principal=excluded.eje_principal, ejes=excluded.ejes, periodo=excluded.periodo, desafio_inicial=excluded.desafio_inicial, descripcion=excluded.descripcion, poblacion=excluded.poblacion, resultados_alcanzados=excluded.resultados_alcanzados, factores_exito=excluded.factores_exito, dificultades=excluded.dificultades, aprendizajes=excluded.aprendizajes, elementos_adaptables=excluded.elementos_adaptables, condiciones_adaptacion=excluded.condiciones_adaptacion, accion_sugerida=excluded.accion_sugerida, instrumentos=excluded.instrumentos, fuentes_verificacion=excluded.fuentes_verificacion;
